import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.BG8d4IEm.js";const b=JSON.parse('{"title":"github","description":"","frontmatter":{"title":"github","tags":["git"],"birth":"2017-01-12T00:00:00.000Z","modified":"2017-01-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/2017-01-12-github.md","filePath":"posts/2017-01-12-github.md"}'),r={name:"posts/2017-01-12-github.md"};function o(s,e,h,g,n,p){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="github" tabindex="-1">github <a class="header-anchor" href="#github" aria-label="Permalink to &quot;github&quot;">​</a></h1><p><strong>github 的使用笔记</strong></p><h2 id="github-pages" tabindex="-1">github pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;github pages&quot;">​</a></h2><h3 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h3><p>github 提供 <code>&lt;username&gt;.github.io</code> 的域名,作为用户 github 仓库静态服务的地址. github page 存在两种类型.</p><ul><li><p>用户或组织的主页</p><ul><li>仓库名必须为 <code>&lt;username&gt;.github.io</code></li><li>整个 master 分支下的内容用来编译生成你的主页</li><li>仓库根目录,映射地址为 <code>&lt;username&gt;.github.io/</code></li></ul></li><li><p>用户或组织项目主页</p><ul><li>master 或 gh-pages 整个分支编译生成项目主页</li><li>只使用 master 下的 <code>docs</code> 文件夹作为项目主页</li><li>项目根目录或 docs 目录,映射地址为 <code>&lt;username&gt;.github.io/&lt;projectname&gt;/</code></li></ul></li></ul><p>路径映射原理参见 <a href="https://help.github.com/articles/user-organization-and-project-pages/" target="_blank" rel="noreferrer">用户组织项目页面</a>. 使用 github page 具有如下限制</p><ul><li>资料内容不大于 1GB</li><li>流量限制 100GB/月</li><li>编译限制 10/小时</li></ul><p>github 主页除了利用 html ,还可使用 <a href="https://jekyllrb.com/docs/installation/" target="_blank" rel="noreferrer">Jekyll</a> 来编译生成静态页面.</p><h2 id="github-pages-快速配置" tabindex="-1">github pages 快速配置 <a class="header-anchor" href="#github-pages-快速配置" aria-label="Permalink to &quot;github pages 快速配置&quot;">​</a></h2><p>下面以用户 github pages 为例讲解配置步骤. 项目中的 github pages 类似.</p><ol><li><p>在 github 主页创建仓库名为 <code>&lt;username&gt;.github.io</code> 的项目</p></li><li><p>在创建的项目的 <code>Settings</code> 选项 <code>github pages</code> 区域</p><ul><li>选择以 master branch 为主页 (默认纪委该选项)</li></ul></li><li><p>在仓库中中添加 <code>index.html</code> 文件内容为</p></li></ol><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">&lt;</span><span style="color:#85E89D;">h1</span><span style="color:#E1E4E8;">&gt;hello world!&lt;/</span><span style="color:#85E89D;">h1</span><span style="color:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="4"><li>保存修改后,访问 <code>http(s)://&lt;username&gt;.github.io/index.html</code> 即可查看到内容.</li></ol><p>可参考</p><ul><li><a href="https://help.github.com/categories/customizing-github-pages/" target="_blank" rel="noreferrer">github pages 自定义</a></li><li><a href="https://github.com/showcases/github-pages-examples" target="_blank" rel="noreferrer">github pages demo</a></li></ul><h2 id="使用-jekyll-编译原始内容" tabindex="-1">使用 jekyll 编译原始内容 <a class="header-anchor" href="#使用-jekyll-编译原始内容" aria-label="Permalink to &quot;使用 jekyll 编译原始内容&quot;">​</a></h2><ol><li>忽略文件中添加 _<code>site</code> 文件夹作为本地浏览内容</li><li>添加全局配置文件 <code>_config.yml</code></li></ol><p>参看 <a href="http://jmcglone.com/guides/github-pages/" target="_blank" rel="noreferrer">github pages 基本使用</a></p><h2 id="github-key-already-in-use" tabindex="-1">github Key already in use <a class="header-anchor" href="#github-key-already-in-use" aria-label="Permalink to &quot;github Key already in use&quot;">​</a></h2><p><a href="https://help.github.com/articles/error-key-already-in-use/" target="_blank" rel="noreferrer">解决方法</a></p><p>删除仓库中的公钥.在全局设置中添加即可.</p><h2 id="github-api" tabindex="-1">github api <a class="header-anchor" href="#github-api" aria-label="Permalink to &quot;github api&quot;">​</a></h2><ol><li>登录用户后,在 <code>Settings/Developer settings</code> personal access tokens 下生成 token.</li><li>参考 <a href="https://developer.github.com/v3/guides/getting-started/#create-a-repository" target="_blank" rel="noreferrer">api </a> 进行调用</li></ol><p>也可采用其他授权方式调用接口 <a href="https://developer.github.com/v3/auth/#basic-authentication" target="_blank" rel="noreferrer">授权调用</a></p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://jekyllrb.com/" target="_blank" rel="noreferrer">jekyll</a></li><li><a href="https://help.github.com/articles/custom-domain-redirects-for-github-pages-sites/" target="_blank" rel="noreferrer">域名重定向规则</a></li><li><a href="https://pages.github.com/" target="_blank" rel="noreferrer">github.io 快速入门</a></li><li><a href="http://www.worldhello.net/gotgithub/03-project-hosting/050-homepage.html" target="_blank" rel="noreferrer">github.io 搭建</a></li><li><a href="https://help.github.com/categories/customizing-github-pages/" target="_blank" rel="noreferrer">github help</a></li><li><a href="https://help.github.com/articles/configuring-a-publishing-source-for-github-pages/" target="_blank" rel="noreferrer">config github page</a></li><li><a href="https://pages.github.com/" target="_blank" rel="noreferrer">github pages</a></li></ul>',27)])])}const c=t(r,[["render",o]]);export{b as __pageData,c as default};
